// Checkout conversion module - auto-offer logic
// Brainstem directive: paidEvents still zero, prioritize conversion

const { log } = require('../constants/logger.js');
const { getPricing } = require('./pricing-engine.js');

async function applyConversionOffer(session) {
  // If user has high engagement but no purchase, inject a micro-offer
  if (session.pageViews > 3 && !session.hasPaid) {
    const pricing = await getPricing(session.visitorId);
    // Offer 10% discount if pricing is above threshold
    if (pricing.basePrice > 0) {
      const discount = Math.round(pricing.basePrice * 0.1 * 100) / 100;
      session.offer = {
        type: 'micro_discount',
        amount: discount,
        expiresAt: Date.now() + 300000 // 5 min
      };
      log('conversion_offer_applied', { visitorId: session.visitorId, discount });
    }
  }
  return session;
}

async function recordPayment(session, amount) {
  // Record a paid event
  session.hasPaid = true;
  session.paidAmount = amount;
  session.paidAt = Date.now();
  log('payment_recorded', { visitorId: session.visitorId, amount });
  return session;
}

module.exports = { applyConversionOffer, recordPayment };
